// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(uint16 feeRate_, uint128 vBase, uint128 vNft, uint56 changeFee, bytes32 merkleRoot, bool useOracle, bool payRoyalties) public {
        vm.assume(feeRate_ <= 5000);

        address baseToken = address(this);
        address nft = address(this);

        bool ok;
        try c.initialize(baseToken, nft, vBase, vNft, changeFee, feeRate_, merkleRoot, useOracle, payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        vm.assume(ok);

        assertTrue(c.feeRate() == feeRate_);
    }
}
